### Command and Query Base Types

```csharp
using MediatR;
using OneOf;

// Command base (no result)
public interface ICommand : IRequest<Result>
{
}

// Command with result
public interface ICommand<TResponse> : IRequest<Result<TResponse>>
{
}

// Query
public interface IQuery<TResponse> : IRequest<TResponse>
{
}

// Result types
public class Result
{
    public bool IsSuccess { get; }
    public string[] Errors { get; }

    protected Result(bool isSuccess, string[] errors)
    {
        IsSuccess = isSuccess;
        Errors = errors ?? Array.Empty<string>();
    }

    public static Result Success() => new Result(true, null);
    public static Result Failure(params string[] errors) => new Result(false, errors);
}

public class Result<T> : Result
{
    public T Value { get; }

    private Result(bool isSuccess, T value, string[] errors)
        : base(isSuccess, errors)
    {
        Value = value;
    }

    public static Result<T> Success(T value) => new Result<T>(true, value, null);
    public new static Result<T> Failure(params string[] errors) => new Result<T>(false, default, errors);
}
