```csharp
// Commands/CreateClaimCommandValidator.cs
using FluentValidation;

namespace Claims.Application.Commands;

public class CreateClaimCommandValidator : AbstractValidator<CreateClaimCommand>
{
    public CreateClaimCommandValidator()
    {
        RuleFor(x => x.ClaimNumber)
            .NotEmpty().WithMessage("Claim number is required")
            .MaximumLength(50).WithMessage("Claim number cannot exceed 50 characters");

        RuleFor(x => x.PatientId)
            .NotEmpty().WithMessage("Patient ID is required");

        RuleFor(x => x.Amount)
            .GreaterThan(0).WithMessage("Amount must be greater than zero")
            .LessThanOrEqualTo(1000000).WithMessage("Amount cannot exceed $1,000,000");

        RuleFor(x => x.ServiceDate)
            .NotEmpty().WithMessage("Service date is required")
            .LessThanOrEqualTo(DateTime.UtcNow).WithMessage("Service date cannot be in the future");

        RuleFor(x => x.ProviderNpi)
            .NotEmpty().WithMessage("Provider NPI is required")
            .Length(10).WithMessage("Provider NPI must be 10 digits");

        RuleFor(x => x.LineItems)
            .NotEmpty().WithMessage("At least one line item is required")
            .Must(items => items.Sum(i => i.Amount) <= 1000000)
            .WithMessage("Total line items amount cannot exceed $1,000,000");

        RuleForEach(x => x.LineItems)
            .SetValidator(new ClaimLineItemValidator());
    }
}

public class ClaimLineItemValidator : AbstractValidator<ClaimLineItem>
{
    public ClaimLineItemValidator()
    {
        RuleFor(x => x.ServiceCode)
            .NotEmpty().WithMessage("Service code is required");

        RuleFor(x => x.Amount)
            .GreaterThan(0).WithMessage("Line item amount must be greater than zero");

        RuleFor(x => x.Units)
            .GreaterThan(0).WithMessage("Units must be greater than zero");
    }
}
