#### Command Handler

```csharp
// Commands/CreateClaimCommandHandler.cs
using MediatR;
using Microsoft.Extensions.Logging;
using Claims.Domain.Entities;

namespace Claims.Application.Commands;

public class CreateClaimCommandHandler : IRequestHandler<CreateClaimCommand, Result<Guid>>
{
    private readonly ApplicationDbContext _dbContext;
    private readonly ILogger<CreateClaimCommandHandler> _logger;

    public CreateClaimCommandHandler(
        ApplicationDbContext dbContext,
        ILogger<CreateClaimCommandHandler> logger)
    {
        _dbContext = dbContext;
        _logger = logger;
    }

    public async Task<Result<Guid>> Handle(
        CreateClaimCommand request,
        CancellationToken cancellationToken)
    {
        // Business rule validation
        var patient = await _dbContext.Patients
            .FirstOrDefaultAsync(p => p.Id == request.PatientId, cancellationToken);

        if (patient == null)
        {
            return Result<Guid>.Failure("Patient not found");
        }

        if (!patient.IsActive)
        {
            return Result<Guid>.Failure("Patient is not active");
        }

        // Check for duplicate claim number
        var exists = await _dbContext.Claims
            .AnyAsync(c => c.ClaimNumber == request.ClaimNumber, cancellationToken);

        if (exists)
        {
            return Result<Guid>.Failure($"Claim with number {request.ClaimNumber} already exists");
        }

        // Create domain entity
        var claim = new Claim
        {
            Id = Guid.NewGuid(),
            ClaimNumber = request.ClaimNumber,
            PatientId = request.PatientId,
            Amount = request.Amount,
            ServiceDate = request.ServiceDate,
            ProviderNpi = request.ProviderNpi,
            Status = ClaimStatus.Submitted,
            SubmittedDate = DateTime.UtcNow,
            LineItems = request.LineItems.Select(li => new ClaimLineItemEntity
            {
                Id = Guid.NewGuid(),
                ServiceCode = li.ServiceCode,
                Amount = li.Amount,
                Units = li.Units
            }).ToList()
        };

        _dbContext.Claims.Add(claim);
        await _dbContext.SaveChangesAsync(cancellationToken);

        _logger.LogInformation(
            "Claim {ClaimId} created with number {ClaimNumber} for patient {PatientId}",
            claim.Id, claim.ClaimNumber, claim.PatientId);

        return Result<Guid>.Success(claim.Id);
    }
}
