```csharp
// Queries/GetClaimByIdQueryHandler.cs
using MediatR;
using Microsoft.EntityFrameworkCore;
using Dapper;

namespace Claims.Application.Queries;

public class GetClaimByIdQueryHandler : IRequestHandler<GetClaimByIdQuery, ClaimDto>
{
    private readonly ApplicationDbContext _dbContext;

    public GetClaimByIdQueryHandler(ApplicationDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<ClaimDto> Handle(
        GetClaimByIdQuery request,
        CancellationToken cancellationToken)
    {
        // Option 1: Entity Framework with projection (good for simple queries)
        var claim = await _dbContext.Claims
            .AsNoTracking()
            .Where(c => c.Id == request.ClaimId)
            .Select(c => new ClaimDto
            {
                Id = c.Id,
                ClaimNumber = c.ClaimNumber,
                PatientId = c.PatientId,
                PatientName = c.Patient.FirstName + " " + c.Patient.LastName,
                Amount = c.Amount,
                ServiceDate = c.ServiceDate,
                ProviderNpi = c.ProviderNpi,
                ProviderName = c.Provider.Name,
                Status = c.Status.ToString(),
                SubmittedDate = c.SubmittedDate,
                ProcessedDate = c.ProcessedDate,
                LineItems = c.LineItems.Select(li => new ClaimLineItemDto
                {
                    Id = li.Id,
                    ServiceCode = li.ServiceCode,
                    ServiceDescription = li.ServiceCodeLookup.Description,
                    Amount = li.Amount,
                    Units = li.Units
                }).ToList()
            })
            .FirstOrDefaultAsync(cancellationToken);

        return claim;
    }
}

// Option 2: Dapper for complex queries (better performance)
public class GetClaimByIdQueryHandlerDapper : IRequestHandler<GetClaimByIdQuery, ClaimDto>
{
    private readonly IDbConnection _connection;

    public GetClaimByIdQueryHandlerDapper(IDbConnection connection)
    {
        _connection = connection;
    }

    public async Task<ClaimDto> Handle(
        GetClaimByIdQuery request,
        CancellationToken cancellationToken)
    {
        const string sql = @"
            SELECT
                c.Id, c.ClaimNumber, c.PatientId, c.Amount, c.ServiceDate,
                c.ProviderNpi, c.Status, c.SubmittedDate, c.ProcessedDate,
                p.FirstName + ' ' + p.LastName AS PatientName,
                pr.Name AS ProviderName,
                li.Id, li.ServiceCode, li.Amount, li.Units,
                sc.Description AS ServiceDescription
            FROM Claims c
            INNER JOIN Patients p ON c.PatientId = p.Id
            INNER JOIN Providers pr ON c.ProviderNpi = pr.Npi
            LEFT JOIN ClaimLineItems li ON c.Id = li.ClaimId
            LEFT JOIN ServiceCodes sc ON li.ServiceCode = sc.Code
            WHERE c.Id = @ClaimId";

        var claimDictionary = new Dictionary<Guid, ClaimDto>();

        var result = await _connection.QueryAsync<ClaimDto, ClaimLineItemDto, ClaimDto>(
            sql,
            (claim, lineItem) =>
            {
                if (!claimDictionary.TryGetValue(claim.Id, out var claimEntry))
                {
                    claimEntry = claim;
                    claimEntry.LineItems = new List<ClaimLineItemDto>();
                    claimDictionary.Add(claim.Id, claimEntry);
                }

                if (lineItem != null)
                {
                    claimEntry.LineItems.Add(lineItem);
                }

                return claimEntry;
            },
            new { ClaimId = request.ClaimId },
            splitOn: "Id");

        return claimDictionary.Values.FirstOrDefault();
    }
}
