```csharp
// Queries/SearchClaimsQueryHandler.cs
using MediatR;
using Microsoft.EntityFrameworkCore;

namespace Claims.Application.Queries;

public class SearchClaimsQueryHandler
    : IRequestHandler<SearchClaimsQuery, PagedResult<ClaimSummaryDto>>
{
    private readonly ApplicationDbContext _dbContext;

    public SearchClaimsQueryHandler(ApplicationDbContext dbContext)
    {
        _dbContext = dbContext;
    }

    public async Task<PagedResult<ClaimSummaryDto>> Handle(
        SearchClaimsQuery request,
        CancellationToken cancellationToken)
    {
        var query = _dbContext.Claims
            .AsNoTracking()
            .AsQueryable();

        // Apply filters
        if (request.PatientId.HasValue)
        {
            query = query.Where(c => c.PatientId == request.PatientId.Value);
        }

        if (!string.IsNullOrEmpty(request.Status))
        {
            query = query.Where(c => c.Status.ToString() == request.Status);
        }

        if (request.ServiceDateFrom.HasValue)
        {
            query = query.Where(c => c.ServiceDate >= request.ServiceDateFrom.Value);
        }

        if (request.ServiceDateTo.HasValue)
        {
            query = query.Where(c => c.ServiceDate <= request.ServiceDateTo.Value);
        }

        // Get total count
        var totalCount = await query.CountAsync(cancellationToken);

        // Apply pagination and projection
        var items = await query
            .OrderByDescending(c => c.SubmittedDate)
            .Skip((request.PageNumber - 1) * request.PageSize)
            .Take(request.PageSize)
            .Select(c => new ClaimSummaryDto
            {
                Id = c.Id,
                ClaimNumber = c.ClaimNumber,
                PatientName = c.Patient.FirstName + " " + c.Patient.LastName,
                Amount = c.Amount,
                Status = c.Status.ToString(),
                ServiceDate = c.ServiceDate
            })
            .ToListAsync(cancellationToken);

        return new PagedResult<ClaimSummaryDto>
        {
            Items = items,
            TotalCount = totalCount,
            PageNumber = request.PageNumber,
            PageSize = request.PageSize
        };
    }
}
