[standards/application/event-driven/STD-APP-EVT-004-dotnet-cqrs.md#phase-3-controller-integration]

### Phase 3: Controller Integration

Controllers should be thin and only orchestrate MediatR requests.

```csharp
// Controllers/ClaimsController.cs
using MediatR;
using Microsoft.AspNetCore.Mvc;
using Claims.Application.Commands;
using Claims.Application.Queries;

namespace Claims.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ClaimsController : ControllerBase
{
    private readonly IMediator _mediator;
    private readonly ILogger<ClaimsController> _logger;

    public ClaimsController(IMediator mediator, ILogger<ClaimsController> logger)
    {
        _mediator = mediator;
        _logger = logger;
    }

    /// <summary>
    /// Create a new claim
    /// </summary>
    [HttpPost]
    [ProducesResponseType(typeof(Guid), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> CreateClaim(
        [FromBody] CreateClaimCommand command,
        CancellationToken cancellationToken)
    {
        var result = await _mediator.Send(command, cancellationToken);

        if (!result.IsSuccess)
        {
            return BadRequest(new { Errors = result.Errors });
        }

        return CreatedAtAction(
            nameof(GetClaim),
            new { id = result.Value },
            new { ClaimId = result.Value });
    }

    /// <summary>
    /// Get claim by ID
    /// </summary>
    [HttpGet("{id}")]
    [ProducesResponseType(typeof(ClaimDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetClaim(
        Guid id,
        CancellationToken cancellationToken)
    {
        var query = new GetClaimByIdQuery(id);
        var claim = await _mediator.Send(query, cancellationToken);

        if (claim == null)
        {
            return NotFound();
        }

        return Ok(claim);
    }

    /// <summary>
    /// Search claims with filters
    /// </summary>
    [HttpGet]
    [ProducesResponseType(typeof(PagedResult<ClaimSummaryDto>), StatusCodes.Status200OK)]
    public async Task<IActionResult> SearchClaims(
        [FromQuery] SearchClaimsQuery query,
        CancellationToken cancellationToken)
    {
        var result = await _mediator.Send(query, cancellationToken);
        return Ok(result);
    }

    /// <summary>
    /// Approve a claim
    /// </summary>
    [HttpPost("{id}/approve")]
    [ProducesResponseType(StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ValidationProblemDetails), StatusCodes.Status400BadRequest)]
    public async Task<IActionResult> ApproveClaim(
        Guid id,
        [FromBody] ApproveClaimCommand command,
        CancellationToken cancellationToken)
    {
        // Ensure ID from route matches command
        if (id != command.ClaimId)
        {
            return BadRequest("Claim ID mismatch");
        }

        var result = await _mediator.Send(command, cancellationToken);

        if (!result.IsSuccess)
        {
            return BadRequest(new { Errors = result.Errors });
        }

        return Ok();
    }
}
