#### Notification Pattern for Domain Events

```csharp
// Domain/Events/ClaimCreatedEvent.cs
using MediatR;

namespace Claims.Domain.Events;

public record ClaimCreatedEvent : INotification
{
    public Guid ClaimId { get; init; }
    public string ClaimNumber { get; init; }
    public Guid PatientId { get; init; }
    public decimal Amount { get; init; }
    public DateTime CreatedAt { get; init; }
}

// Event Handlers
public class ClaimCreatedEmailHandler : INotificationHandler<ClaimCreatedEvent>
{
    private readonly IEmailService _emailService;

    public ClaimCreatedEmailHandler(IEmailService emailService)
    {
        _emailService = emailService;
    }

    public async Task Handle(ClaimCreatedEvent notification, CancellationToken cancellationToken)
    {
        await _emailService.SendClaimConfirmationEmail(
            notification.PatientId,
            notification.ClaimNumber);
    }
}

public class ClaimCreatedAuditHandler : INotificationHandler<ClaimCreatedEvent>
{
    private readonly IAuditService _auditService;

    public ClaimCreatedAuditHandler(IAuditService auditService)
    {
        _auditService = auditService;
    }

    public async Task Handle(ClaimCreatedEvent notification, CancellationToken cancellationToken)
    {
        await _auditService.LogEvent(
            "ClaimCreated",
            notification.ClaimId,
            notification);
    }
}

// Publishing events from command handler
public class CreateClaimCommandHandler : IRequestHandler<CreateClaimCommand, Result<Guid>>
{
    private readonly ApplicationDbContext _dbContext;
    private readonly IPublisher _publisher;

    public async Task<Result<Guid>> Handle(
        CreateClaimCommand request,
        CancellationToken cancellationToken)
    {
        // ... create claim ...

        await _dbContext.SaveChangesAsync(cancellationToken);

        // Publish domain event
        await _publisher.Publish(new ClaimCreatedEvent
        {
            ClaimId = claim.Id,
            ClaimNumber = claim.ClaimNumber,
            PatientId = claim.PatientId,
            Amount = claim.Amount,
            CreatedAt = DateTime.UtcNow
        }, cancellationToken);

        return Result<Guid>.Success(claim.Id);
    }
}
