### Complete Example: Separating Read/Write Databases

For high-scale applications, you may want separate databases for reads and writes.

```csharp
// Program.cs - Dual database configuration
builder.Services.AddDbContext<WriteDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("WriteConnection")));

builder.Services.AddDbContext<ReadDbContext>(options =>
    options.UseSqlServer(builder.Configuration.GetConnectionString("ReadConnection"))
           .UseQueryTrackingBehavior(QueryTrackingBehavior.NoTracking));

// Command handler using write database
public class CreateClaimCommandHandler : IRequestHandler<CreateClaimCommand, Result<Guid>>
{
    private readonly WriteDbContext _writeDb;

    public CreateClaimCommandHandler(WriteDbContext writeDb)
    {
        _writeDb = writeDb;
    }

    public async Task<Result<Guid>> Handle(...)
    {
        // Use write database for commands
        _writeDb.Claims.Add(claim);
        await _writeDb.SaveChangesAsync(cancellationToken);
        return Result<Guid>.Success(claim.Id);
    }
}

// Query handler using read database
public class GetClaimQueryHandler : IRequestHandler<GetClaimByIdQuery, ClaimDto>
{
    private readonly ReadDbContext _readDb;

    public GetClaimQueryHandler(ReadDbContext readDb)
    {
        _readDb = readDb;
    }

    public async Task<ClaimDto> Handle(...)
    {
        // Use read database for queries
        return await _readDb.Claims
            .AsNoTracking()
            .ProjectTo<ClaimDto>()
            .FirstOrDefaultAsync(c => c.Id == request.ClaimId);
    }
}
